import React, { useEffect, useState } from 'react';
import { ShoppingCart, Info } from 'lucide-react';
import { api } from "../api/index";

// Компонент карточки цветка
const FlowerCard = ({ flower }) => {
  return (
    <div className="bg-[#161b2c] border border-white/10 rounded-2xl overflow-hidden hover:border-indigo-500/50 transition-all duration-300 group">
      {/* Контейнер для фото */}
      <div className="relative h-64 overflow-hidden">
        <img 
          src={flower.image || 'https://images.unsplash.com/photo-1490750967868-88aa4486c946?w=600'} 
          alt={flower.name}
          className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500"
        />
        <div className="absolute top-3 right-3 bg-indigo-600/90 text-white text-xs font-bold px-3 py-1 rounded-full">
          {flower.category}
        </div>
      </div>

      {/* Контент карточки */}
      <div className="p-5">
        <div className="flex justify-between items-start mb-2">
          <h3 className="text-xl font-bold text-white">{flower.name}</h3>
          <span className="text-indigo-400 font-bold text-lg">{flower.price} ₽</span>
        </div>

        <p className="text-gray-400 text-sm mb-4 line-clamp-2">
          {flower.description || "Прекрасный выбор для подарка близким."}
        </p>

        <div className="flex items-center justify-between gap-3">
          <div className="text-xs text-gray-500">
            В наличии: <span className={flower.count > 0 ? "text-green-400" : "text-red-400"}>
              {flower.count} шт.
            </span>
          </div>
          <button 
            disabled={flower.count === 0}
            className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-500 disabled:bg-gray-700 text-white px-4 py-2 rounded-xl font-medium transition-colors"
            onClick={() => alert(`Добавлено: ${flower.name}`)}
          >
            <ShoppingCart size={18} />
            Купить
          </button>
        </div>
      </div>
    </div>
  );
};

// Основная страница магазина
export default function ShopPage() {
  const [flowers, setFlowers] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadFlowers = async () => {
      try {
        const data = await api.getFlowers();
        setFlowers(data);
      } catch (error) {
        console.error("Ошибка загрузки:", error);
      } finally {
        setLoading(false);
      }
    };
    loadFlowers();
  }, []);

  return (
    <div className="min-h-screen bg-[#0b0f19] text-[#e7eaf3] font-sans">
      {/* Шапка */}
      <header className="border-b border-white/10 bg-white/5 sticky top-0 backdrop-blur-md z-50">
        <div className="max-w-7xl mx-auto px-4 py-4 flex justify-between items-center">
          <div className="text-2xl font-black text-indigo-500 tracking-tighter">FLOWER SHOP</div>
          <nav className="flex gap-6 text-sm font-medium">
            <a href="#" className="hover:text-indigo-400 transition-colors">Каталог</a>
            <a href="#" className="hover:text-indigo-400 transition-colors">О нас</a>
            <button className="relative">
              <ShoppingCart size={24} />
              <span className="absolute -top-2 -right-2 bg-indigo-600 text-[10px] w-4 h-4 rounded-full flex items-center justify-center">0</span>
            </button>
          </nav>
        </div>
      </header>

      {/* Основной контент */}
      <main className="max-w-7xl mx-auto px-4 py-10">
        <div className="flex flex-col mb-10">
          <h1 className="text-4xl font-bold mb-2">Наш ассортимент</h1>
          <p className="text-gray-400">Свежие цветы с доставкой прямо к вашему порогу</p>
        </div>

        {loading ? (
          <div className="flex justify-center py-20">
            <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-indigo-500"></div>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
            {flowers.map(flower => (
              <FlowerCard key={flower.id} flower={flower} />
            ))}
          </div>
        )}

        {!loading && flowers.length === 0 && (
          <div className="text-center py-20 bg-white/5 rounded-3xl border border-dashed border-white/10">
            <Info className="mx-auto mb-4 text-gray-500" size={48} />
            <p className="text-xl text-gray-400">К сожалению, цветов сейчас нет в наличии</p>
          </div>
        )}
      </main>
    </div>
  );
}
